assert.equal(tools[0].inputSchema.additionalProperties, false);
assert.deepEqual(tools[0].inputSchema.required, ["user_ids"]);
assert.equal(tools[0].inputSchema.properties.user_ids.maxItems, 5);
assert.equal(tools[0].inputSchema.properties.user_ids.minItems, 1);
assert.equal(tools[0].inputSchema.properties.user_ids.uniqueItems, true);

