try { await callTool("users_get_many", { user_ids: "u1" }); throw new Error("should have thrown"); }
catch (e) { assert.match(e.message, /array/); }

// empty array rejected
try { await callTool("users_get_many", { user_ids: [] }); throw new Error("should have thrown"); }
catch (e) { assert.match(e.message, /non-empty/); }

// too many entries rejected
try { await callTool("users_get_many", { user_ids: ["a","b","c","d","e","f"] }); throw new Error("should have thrown"); }
catch (e) { assert.match(e.message, /at most 5/); }

// non-string element rejected
try { await callTool("users_get_many", { user_ids: ["u1", 5] }); throw new Error("should have thrown"); }
catch (e) { assert.match(e.message, /only strings/); }

// extra field rejected
try { await callTool("users_get_many", { user_ids: ["u1"], extra: 1 }); throw new Error("should have thrown"); }
catch (e) { assert.match(e.message, /Unexpected fields/); }

// unknown tool rejected
try { await callTool("users_get_unknown", { user_ids: ["u1"] }); throw new Error("should have thrown"); }
catch (e) { assert.match(e.message, /Unknown tool/); }

// exactly 5 entries ok (boundary)
r = await callTool("users_get_many", { user_ids: ["u1","u2","u3","x","y"] });
assert.match(r.content[0].text, /u1: Ada[\s\S]*x: not found[\s\S]*y: not found/);

console.log("All extra checks passed");
'"}

